-- ====================================================================
-- SQL SCHEMA FOR TABLE public.customers
-- ====================================================================

-- 1. Create Table public.customers
CREATE TABLE IF NOT EXISTS public.customers (
  id text PRIMARY KEY,
  name text NOT NULL,
  phone text,
  email text,
  address text,
  customer_type text,
  marital_status text,
  join_date date,
  points integer DEFAULT 0,
  total_transactions integer DEFAULT 0,
  total_spent numeric DEFAULT 0,
  segment text,
  last_transaction date,
  status text DEFAULT 'Aktif',
  notes text,
  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
  updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 2. Enable Row Level Security (RLS)
ALTER TABLE public.customers ENABLE ROW LEVEL SECURITY;

-- 3. Kebijakan Keamanan (RLS Policies)
DROP POLICY IF EXISTS "Public can read customers" ON public.customers;
DROP POLICY IF EXISTS "Authenticated can insert customers" ON public.customers;
DROP POLICY IF EXISTS "Authenticated can update customers" ON public.customers;
DROP POLICY IF EXISTS "Authenticated can delete customers" ON public.customers;

-- Izinkan semua pengguna (termasuk anonim) untuk select/membaca data pelanggan (agar sinkronisasi lancar)
CREATE POLICY "Public can read customers" ON public.customers FOR SELECT USING (true);

-- Hanya pengguna terautentikasi (admin/kasir) yang bisa menambah, mengubah, atau menghapus pelanggan
CREATE POLICY "Authenticated can insert customers" ON public.customers FOR INSERT TO authenticated WITH CHECK (true);
CREATE POLICY "Authenticated can update customers" ON public.customers FOR UPDATE TO authenticated USING (true) WITH CHECK (true);
CREATE POLICY "Authenticated can delete customers" ON public.customers FOR DELETE TO authenticated USING (true);

-- Trigger untuk otomatis memperbarui updated_at jika baris diubah
CREATE OR REPLACE FUNCTION public.handle_customer_updated_at()
RETURNS trigger AS $$
BEGIN
  new.updated_at = timezone('utc'::text, now());
  RETURN new;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS on_customer_updated ON public.customers;
CREATE TRIGGER on_customer_updated
  BEFORE UPDATE ON public.customers
  FOR EACH ROW EXECUTE PROCEDURE public.handle_customer_updated_at();

